  'cmp.explore':      { en:'First Explore', zh:'首次探索', ja:'初回探索', ko:'첫 탐색', es:'Primera Exploración', fr:'Première Exploration', de:'Erste Erkundung', pt:'Primeira Exploração', ru:'Первое исследование', ar:'الاستكشاف الأول', it:'Prima Esplorazione', hi:'पहली खोज' },
